    "about_title": "About AgriMind AI",
    "about_subtitle": "Empowering Indian farmers through accessible, science-backed artificial intelligence and agronomic decision tools.",
    "about_eyebrow": "MISSION & VALUES",
    "about_mission_title": "Why We Built AgriMind AI",
    "about_mission_desc": "Agriculture is the backbone of India, supporting over 600 million livelihoods. Yet smallholder farmers often lack immediate access to certified plant pathologists, timely market intelligence, and customized soil diagnostic advice. AgriMind AI bridges this gap by bringing verified packages of practices into simple regional-language digital tools.",
    "about_pillars_title": "Our Four Pillars of Agricultural Technology",
    "about_pillar1_title": "1. Zero Subscription Barriers",
    "about_pillar1_desc": "Essential crop diagnostics, market intelligence, and irrigation calculations must remain free and accessible to every cultivator.",
    "about_pillar2_title": "2. Complete Regional Accessibility",
    "about_pillar2_desc": "Built natively in English, Telugu, Tamil, and Hindi so complex agronomic advice is easily understandable.",
    "about_pillar3_title": "3. Science-Backed Agronomy",
    "about_pillar3_desc": "Rules and schedules derived from ICAR, State Agricultural Universities, and FAO benchmark standards.",
    "about_pillar4_title": "4. Transparent AI Limitations",
    "about_pillar4_desc": "We clearly disclose prototype boundaries and always advocate consulting certified local KVK agronomists before spraying.",
    "about_story_title": "From Laboratory to the Farmer's Pocket",
    "about_story_desc": "Modern agriculture produces enormous volumes of meteorological data, soil maps, and commodity statistics. By translating these into offline-friendly, high-contrast, responsive tools, AgriMind AI helps farmers make confident choices every season.",
    "about_ethical_title": "Our Ethical Commitment to Farmers",
    "about_ethical_desc": "We do not sell unverified agrochemicals, take commissions on mandi trades, or hoard user farm data on hidden servers. All your farm inputs and schedules remain safely stored on your own device.",
    "contact_title": "Contact & Support",
    "contact_subtitle": "Have a question about our farming tools or want to partner with AgriMind AI? Get in touch with our agronomy support team.",
