    "privacy_title": "Privacy Policy & Data Transparency",
    "privacy_subtitle": "How AgriMind AI handles your farm inputs, schedules, and reminders with complete transparency and local device privacy.",
    "privacy_eyebrow": "DATA INTEGRITY & PRIVACY",
    "privacy_sec1_title": "1. Client-Side Processing Architecture",
    "privacy_sec1_desc": "AgriMind AI is engineered as a privacy-first static web application. All crop planning algorithms, soil health diagnostics, weather simulations, and profit calculations execute entirely inside your local web browser.",
    "privacy_sec2_title": "2. Handling of Uploaded Crop Photographs",
    "privacy_sec2_desc": "When you select or drag-and-drop a crop leaf photograph in the AI Crop Doctor tool:",
    "privacy_sec3_title": "3. Use of Browser LocalStorage",
    "privacy_sec3_desc": "AgriMind AI uses your browser's local storage solely for preserving non-sensitive operational states across sessions, including:",
    "privacy_sec4_title": "4. Absence of User Accounts & Passwords",
    "privacy_sec4_desc": "If you send an inquiry via our contact form, your details are used solely to reply to your question. We never sell farmer contact lists to commercial agrochemical manufacturers or third-party advertisers.",
