    "about_hero_eyebrow": "OUR MISSION & PHILOSOPHY",
    "about_hero_title": "About AgriMind AI",
    "about_hero_desc": "Democratizing agronomic intelligence, soil health science, and transparent market economics for every Indian farmer.",
    "about_why_title": "Why AgriMind AI Was Created",
    "about_why_p1": "Indian agriculture is the backbone of the nation's economy, employing over 50% of the workforce. Yet, smallholder farmers often face fragmented extension services, delayed pest advisories, and unpredictable mandi auctions.",
    "about_why_p2": "AgriMind AI was conceived to bridge this gap by synthesizing certified ICAR agronomy recommendations, local weather patterns, and real-time mandi prices into a seamless, fast, accessible digital platform.",
    "about_principles_title": "Our Architectural Principles",
    "about_principle_1_title": "🔬 Transparent Agronomy",
    "about_principle_1_desc": "We never disguise rule-based estimations as infallible black-box predictions. Every dosage, timeline, and suitability rating explains the underlying soil chemistry, pest lifecycle, and economic reasoning.",
    "about_principle_2_title": "🌐 Regional Linguistic Access",
    "about_principle_2_desc": "Agricultural technology creates no real value if locked in technical English. AgriMind AI is built native-first in Telugu, Tamil, Hindi, and English with regional agricultural terminologies.",
    "about_principle_3_title": "💧 Conservation-First",
    "about_principle_3_desc": "Every crop and irrigation calculation prioritizes groundwater preservation, micro-irrigation scheduling, and soil organic carbon revitalization over short-term exploitative yields.",
    "about_principle_4_title": "⚡ Zero-Friction Web Delivery",
    "about_principle_4_desc": "Fast, lightweight, static client architecture without complex app store downloads, logins, or tracking. It loads instantly even on low-bandwidth rural mobile networks.",
    "contact_desc": "Have feedback on our prototype tools or suggestions for regional agricultural university collaboration? Send our agronomy team a message.",
    "contact_subject_label": "Subject *",
    "contact_subject_placeholder": "Select an inquiry category",
    "contact_cat_feedback": "General Platform Feedback",
