    "contact_submit_btn": "Submit Demonstration Message",
    "contact_demo_notice": "Your submission has been captured in this prototype demonstration. In production, our agronomists respond within 24 hours.",
    "privacy_desc": "Transparent disclosure of data handling, browser storage, and client-side processing policies for AgriMind AI.",
    "privacy_sec2_li1": "No image files are transmitted across the internet to any external server.",
    "privacy_sec2_li2": "No biometric or facial data is captured or retained.",
    "privacy_sec2_li3": "When you refresh or close the browser tab, the previewed image is immediately released from memory.",
    "privacy_sec3_li1": "We do not store passwords, tokens, API keys, location coordinates, or banking details.",
    "home_landscape_eyebrow": "THE AGRICULTURAL LANDSCAPE",
    "home_landscape_title": "Bridging Complex Science and Daily Farming Realities",
    "home_landscape_desc": "Indian farmers face erratic rainfall patterns, unexpected pest outbreaks, and fluctuating mandi prices without clear agronomic guidance.",
    "home_problem_1_title": "Uncertain Disease Outbreaks",
    "home_problem_1_desc": "Blights, wilts, and leaf curls cause up to 30% yield loss when diagnosed late without expert intervention.",
    "home_problem_2_title": "Imbalanced Fertilizer Application",
    "home_problem_2_desc": "Surplus urea usage has skewed N:P:K ratios across major agricultural tracts, degrading soil microbiology.",
    "home_solution_title": "The AgriMind AI Solution",
    "home_solution_desc": "Practical decision-support tools built upon verified ICAR agronomy guidelines, local weather simulation, and transparent market economics.",
    "home_workflow_eyebrow": "HOW IT WORKS",
    "home_workflow_title": "Four Steps to Smarter Farm Decisions",
    "home_workflow_subtitle": "From soil testing to harvest marketing, navigate every crop milestone with intelligent guidance.",
    "home_step_1_title": "1. Assess Soil & Weather",
    "home_step_1_desc": "Enter your soil test readings or select regional presets to understand pH, organic carbon, and macro-nutrients.",
    "home_step_2_title": "2. Plan the Right Crop",
    "home_step_2_desc": "Match agro-ecological suitability, water requirements, and investment capacity for the upcoming season.",
    "home_step_3_title": "3. Monitor Health & Tasks",
    "home_step_3_desc": "Scan symptomatic leaves for early disease diagnosis and follow our dynamic farming calendar.",
    "home_step_4_title": "4. Maximize Profit at Mandi",
    "home_step_4_desc": "Simulate crop production costs, track nearby mandi prices, and discover optimal harvest sales windows.",
    "home_stats_farmers": "Zero mandatory subscription",
    "home_stats_yield": "Scientific agronomy rules",
    "home_stats_water": "Precision water savings",
    "home_faq_eyebrow": "FREQUENTLY ASKED QUESTIONS",
    "home_faq_title": "Answers to Common Farm Questions",
    "home_faq_subtitle": "Clear explanations of our technology, agronomic principles, and regional data sources.",
    "home_faq_q1": "How accurate is the AI Crop Doctor?",
    "home_faq_a1": "Our diagnostic engine uses curated symptom matrices validated by ICAR plant pathology guides for paddy, tomato, cotton, and wheat. While it provides strong indicative diagnostics, we always recommend verifying with your local KVK for large-scale outbreaks.",
    "home_faq_q2": "Does AgriMind AI require an internet connection?",
    "home_faq_a2": "The website requires an initial connection to load, but all calculations, soil diagnostics, calendars, and profit estimations run client-side inside your browser without uploading your photos or farm data to external servers.",
    "home_faq_q3": "Are the mandi market prices real-time?",
    "home_faq_a3": "Our demo database simulates active Agmarknet and e-NAM price ranges across key Indian states with daily arrival volumes and 30-day historical trends for major crops.",
    "home_faq_q4": "Is AgriMind AI free for Indian farmers?",
    "home_faq_a4": "Yes, 100% free with no mandatory subscriptions, advertisements, or hidden paywalls. It is built as an open demonstration of modern agricultural web technology.",
    "home_cta_title": "Start Farming Smarter Today",
    "home_cta_desc": "Join forward-thinking farmers across India using data and science to protect yields and maximize market profits.",
    "home_cta_btn1": "Explore AI Tools",
    "home_cta_btn2": "Read Farming Guides",
