    "about_title": "మా గురించి — అగ్రిమైండ్ AI",
    "about_subtitle": "రైతులకు అందుబాటులో ఉండే అత్యాధునిక AI సాంకేతికత ద్వారా భారతీయ వ్యవసాయాన్ని బలోపేతం చేయడమే మా లక్ష్యం.",
    "about_eyebrow": "మా లక్ష్యం & విలువలు",
    "about_mission_title": "మేము అగ్రిమైండ్ AI ని ఎందుకు నిర్మించాము",
    "about_mission_desc": "భారతదేశంలో 60 కోట్ల మందికి పైగా ప్రజలు వ్యవసాయంపై ఆధారపడి జీవిస్తున్నారు. సకాలంలో వ్యవసాయ నిపుణుల సలహాలు, మార్కెట్ ధరలు మరియు నేల పరీక్షల సమాచారం అందక రైతులు నష్టపోతున్నారు. ఈ సమస్యను పరిష్కరించి, విశ్వసనీయ సమాచారాన్ని ప్రాంతీయ భాషల్లో అందించడమే అగ్రిమైండ్ AI ధ్యేయం.",
    "about_pillars_title": "మా వ్యవసాయ సాంకేతిక స్తంభాలు",
    "about_pillar1_title": "1. పూర్తిగా ఉచిత సేవలు",
    "about_pillar1_desc": "పంట పరీక్షలు, మార్కెట్ సమాచారం మరియు నీటి ప్రణాళిక ప్రతి రైతుకూ ఉచితంగా అందాలి.",
    "about_pillar2_title": "2. ప్రాంతీయ భాషల్లో సమాచారం",
    "about_pillar2_desc": "రైతులకు సులభంగా అర్థమయ్యేలా ఇంగ్లీష్, తెలుగు, తమిళం మరియు హిందీ భాషల్లో పూర్తి సమాచారం.",
    "about_pillar3_title": "3. శాస్త్రీయ వ్యవసాయ ఆధారాలు",
    "about_pillar3_desc": "ICAR, వ్యవసాయ విశ్వవిద్యాలయాలు మరియు FAO మార్గదర్శకాల ఆధారంగా రూపొందించిన సూచనలు.",
    "about_pillar4_title": "4. పారదర్శక బాధ్యత",
    "about_pillar4_desc": "రసాయనాలు వాడే ముందు ఎల్లప్పుడూ క్షేత్రస్థాయి KVK అధికారులను సంప్రదించాలని మేము స్పష్టంగా తెలియజేస్తాము.",
    "about_story_title": "ప్రయోగశాల నుండి రైతు చేతిలోకి",
    "about_story_desc": "వాతావరణ సమాచారం, నేల పటాలు మరియు మార్కెట్ ధరలను సరళమైన మొబైల్ సాధనాలుగా మార్చి రైతులకు అందుబాటులోకి తెస్తున్నాము.",
    "about_ethical_title": "రైతులకు మా నైతిక నిబద్ధత",
