    "about_hero_eyebrow": "మా లక్ష్యం & సిద్ధాంతం",
    "about_hero_title": "అగ్రిమైండ్ AI గురించి",
    "about_hero_desc": "భారతీయ రైతులందరికీ వ్యవసాయ విజ్ఞానం, భూసార శాస్త్రం మరియు మార్కెట్ సమాచారాన్ని సులభంగా అందించడం.",
    "about_why_title": "అగ్రిమైండ్ AI ఎందుకు సృష్టించబడింది?",
    "about_why_p1": "భారత ఆర్థిక వ్యవస్థకు వ్యవసాయమే వెన్నెముక. అయినప్పటికీ, చిన్న, సన్నకారు రైతులు సరైన సమయంలో తెగుళ్ల సమాచారం లేక, మార్కెట్ ధరల హెచ్చుతగ్గులతో నష్టపోతున్నారు.",
    "about_why_p2": "రైతులకు అధికారిక ICAR సిఫార్సులు, స్థానిక వాతావరణం మరియు ప్రత్యక్ష మండి ధరలను వేగంగా మరియు సులభంగా అందించడమే అగ్రిమైండ్ AI ముఖ్య ఉద్దేశ్యం.",
    "about_principles_title": "మా ప్రాథమిక సూత్రాలు",
    "about_principle_1_title": "🔬 పారదర్శక వ్యవసాయ శాస్త్రం",
    "about_principle_1_desc": "మేము ఎలాంటి రహస్య పద్ధతులు ఉపయోగించము. ప్రతి పంట కాలపరిమితి, ఎరువుల మోతాదు మరియు సలహాలు శాస్త్రీయ భూసార విశ్లేషణ మరియు పరిశోధనలపై ఆధారపడి ఉంటాయి.",
    "about_principle_2_title": "🌐 ప్రాంతీయ భాషల సౌలభ్యం",
    "about_principle_2_desc": "సాంకేతిక పరిజ్ఞానం కేవలం ఆంగ్లంలో ఉంటే రైతులకు ఉపయోగపడదు. అందుకే అగ్రిమైండ్ AI తెలుగు, తమిళం, హిందీ మరియు ఆంగ్లంలో సహజమైన పదాలతో రూపొందించబడింది.",
    "about_principle_3_title": "💧 నీటి సంరక్షణకు ప్రాధాన్యత",
    "about_principle_3_desc": "ప్రతి పంట మరియు నీటి ప్రణాళిక భూగర్భ జలాల పరిరక్షణ, బిందు సేద్యం మరియు భూసారాన్ని పెంచే విధంగా రూపకల్పన చేయబడింది.",
    "about_principle_4_title": "⚡ వేగవంతమైన పనితీరు",
    "about_principle_4_desc": "యాప్ స్టోర్ డౌన్‌లోడ్‌లు లేదా లాగిన్‌లు లేకుండా గ్రామీణ ప్రాంతాల్లో నెమ్మదైన ఇంటర్నెట్‌లో కూడా అత్యంత వేగంగా పనిచేసే విధంగా ఇది నిర్మించబడింది.",
