    "home_landscape_desc": "భారతీయ రైతులు మారుతున్న వర్షపాతం, ఊహించని తెగుళ్లు మరియు మార్కెట్ ధరల హెచ్చుతగ్గులతో సతమతమవుతున్నారు.",
