    "home_solution_desc": "ICAR మార్గదర్శకాలు, స్థానిక వాతావరణం మరియు మార్కెట్ ధరల ఆధారంగా రైతులకు నమ్మకమైన డిజిటల్ తోడ్పాటు.",
