    "home_workflow_title": "నాలుగు సులభమైన దశల్లో స్మార్ట్ వ్యవసాయం",
    "home_workflow_subtitle": "భూసార పరీక్ష నుండి పంట మార్కెటింగ్ వరకు ప్రతి దశలో మీకు సరైన సహాయం.",
    "home_step_1_title": "1. నేల & వాతావరణాన్ని పరీక్షించండి",
    "home_step_1_desc": "మీ నేల పరీక్ష వివరాలను నమోదు చేసి లేదా ప్రాంతీయ ప్రీసెట్లను ఎంచుకుని pH మరియు పోషకాలను తెలుసుకోండి.",
    "home_step_2_title": "2. సరైన పంటను ఎంచుకోండి",
    "home_step_2_desc": "రాబోయే సీజన్ కోసం నేల రకం, నీటి వసతి మరియు పెట్టుబడి సామర్థ్యానికి సరిపోయే పంటలను ఎంచుకోండి.",
    "home_step_3_title": "3. పంట ఆరోగ్యం & పనులను పర్యవేక్షించండి",
    "home_step_3_desc": "ఆకు ఫోటోలతో తెగుళ్లను గుర్తించండి మరియు వ్యవసాయ క్యాలెండర్ ద్వారా పనులను సమయానికి పూర్తి చేయండి.",
    "home_step_4_title": "4. మార్కెట్లో గరిష్ట లాభం పొందండి",
    "home_step_4_desc": "ఖర్చులను అంచనా వేయండి, సమీప మండి ధరలను గమనించండి మరియు సరైన సమయంలో విక్రయించి లాభపడండి.",
