    "home_faq_title": "రైతుల సందేహాలకు సమాధానాలు",
    "home_faq_subtitle": "మా సాంకేతికత, వ్యవసాయ సూత్రాలు మరియు సమాచార వనరుల గురించిన పూర్తి వివరాలు.",
    "home_faq_q1": "AI పంట వైద్యుడు ఎంతవరకు ఖచ్చితమైనది?",
    "home_faq_a1": "మా వ్యవస్థ వరి, టమాటా, పత్తి మరియు గోధుమ పంటలలోని తెగుళ్లను ఖచ్చితంగా గుర్తించడానికి ICAR మార్గదర్శకాలను ఉపయోగిస్తుంది. తీవ్రమైన వ్యాధులకు స్థానిక KVK అధికారుల సలహా తీసుకోవాలని మేము సిఫార్సు చేస్తున్నాము.",
    "home_faq_q2": "అగ్రిమైండ్ AI ఉపయోగించడానికి ఇంటర్నెట్ అవసరమా?",
    "home_faq_a2": "వెబ్‌సైట్ తెరవడానికి మొదట ఇంటర్నెట్ కావాలి, కానీ పంట ప్రణాళికలు, భూసార పరీక్షలు మరియు క్యాలెండర్ లెక్కింపులన్నీ మీ ఫోన్ బ్రౌజర్‌లోనే జరుగుతాయి.",
    "home_faq_q3": "మండి మార్కెట్ ధరలు తాజావేనా?",
    "home_faq_a3": "మా వ్యవస్థ ప్రధాన భారతీయ మార్కెట్లలోని e-NAM మరియు Agmarknet ధరల సరళిని, రోజువారీ రాకలను మరియు 30 రోజుల ధరల హెచ్చుతగ్గులను ప్రతిబింబిస్తుంది.",
    "home_faq_q4": "అగ్రిమైండ్ AI భారతీయ రైతులకు ఉచితమా?",
    "home_faq_a4": "అవును, పూర్తిగా ఉచితం! ఎలాంటి చందా రుసుములు, ప్రకటనలు లేదా దాచిన రుసుములు లేవు. రైతుల శ్రేయస్సు కోసమే ఇది నిర్మించబడింది.",
