    "footer_contact": "தொடர்பு கொள்ள",
    "footer_disclaimer_note": "அக்ரிமைண்ட் AI ஒரு மாதிரி கல்விச் செயல்விளக்கம் மட்டுமே. விவசாய முடிவுகளை எடுக்கும் முன் உள்ளூர் வேளாண் வல்லுநர்களின் ஆலோசனையைப் பெறவும்.",
