    "footer_helpline_sub": "24 மணி நேரமும் இலவச வேளாண் ஆலோசனை சேவை.",
    "footer_resources_title": "வளங்கள்",
    "footer_tools_title": "AI முடிவெடுக்கும் கருவிகள்",
