    "doctor_subtitle": "பாதிக்கப்பட்ட பயிர் இலையின் புகைப்படத்தை பதிவேற்றி, நோய் அறிகுறிகள் மற்றும் தடுப்பு முறைகளை உடனே அறியவும்.",
