    "about_title": "எங்களைப் பற்றி — அக்ரிமைண்ட் AI",
    "about_subtitle": "அணுகக்கூடிய, அறிவியல் பூர்வ AI தொழில்நுட்பம் மூலம் இந்திய விவசாயிகளை மேம்படுத்துவதே எங்கள் நோக்கம்.",
    "about_eyebrow": "எங்கள் நோக்கம் & கொள்கைகள்",
    "about_mission_title": "அக்ரிமைண்ட் AI உருவான நோக்கம்",
    "about_mission_desc": "இந்தியாவில் 60 கோடிக்கும் அதிகமான மக்கள் விவசாயத்தை வாழ்வாதாரமாகக் கொண்டுள்ளனர். வேளாண் வல்லுநர்களின் உடனடி ஆலோசனைகள், சந்தை நிலவரம் விவசாயிகளுக்கு சரியான நேரத்தில் கிடைப்பதை அக்ரிமைண்ட் AI உறுதி செய்கிறது.",
    "about_pillars_title": "எங்கள் நான்கு தூண்கள்",
    "about_pillar1_title": "1. கட்டணமில்லா சேவை",
    "about_pillar1_desc": "அனைத்து அடிப்படை வேளாண் கருவிகளும் எந்தவொரு கட்டணமும் இன்றி விவசாயிகளுக்கு கிடைக்க வேண்டும்.",
    "about_pillar2_title": "2. பிராந்திய மொழி பயன்பாடு",
    "about_pillar2_desc": "விவசாயிகள் எளிதில் புரிந்துகொள்ளும் வகையில் தமிழ், தெலுங்கு, இந்தி மற்றும் ஆங்கிலத்தில் முழு ஆதரவு.",
    "about_pillar3_title": "3. அறிவியல் பூர்வ நெறிமுறைகள்",
    "about_pillar3_desc": "ICAR மற்றும் தமிழ்நாடு வேளாண் பல்கலைக்கழகத்தின் அங்கீகரிக்கப்பட்ட நடைமுறைகளின் அடிப்படையில் உருவானது.",
    "about_pillar4_title": "4. வெளிப்படைத்தன்மை",
    "about_pillar4_desc": "ரசாயன மருந்துகளுக்கு முன் உள்ளூர் வேளாண் அறிவியல் மைய (KVK) அதிகாரிகளை அணுகுமாறு அறிவுறுத்துகிறோம்.",
    "about_story_title": "ஆய்வகத்திலிருந்து உழவரின் கைக்கு",
    "about_story_desc": "வானிலை தரவுகள், மண் வரைபடங்கள் மற்றும் சந்தை நிலவரங்களை எளிய மொபைல் கருவிகளாக மாற்றி விவசாயிகளுக்கு வழங்குகிறோம்.",
    "about_ethical_title": "விவசாயிகளுக்கான எங்கள் உறுதிமொழி",
    "about_ethical_desc": "நாங்கள் விவசாயிகளின் தரவுகளை சேமிப்பதோ அல்லது வணிக நோக்கங்களுக்காக பயன்படுத்துவதோ இல்லை. உங்கள் தகவல்கள் உங்கள் சாதனத்திலேயே பாதுகாப்பாக இருக்கும்.",
