    "sec2_eyebrow": "भारतीय कृषि परिदृश्य",
    "sec2_title": "वैज्ञानिक अनुसंधान और व्यावहारिक खेती का संगम",
    "sec2_subtitle": "अनियमित वर्षा, अप्रत्याशित कीट प्रकोप, घटती मृदा उर्वरता और बाज़ार के उतार-चढ़ाव से निपटने के लिए एग्रीमाइंड एआई सरल क्षेत्रीय भाषाओं में वैज्ञानिक समाधान उपलब्ध कराता है।",
