    "about_hero_eyebrow": "हमारा लक्ष्य एवं दृष्टिकोण",
    "about_hero_title": "एग्रीमाइंड एआई के बारे में",
    "about_hero_desc": "प्रत्येक भारतीय किसान तक आधुनिक कृषि विज्ञान, मृदा स्वास्थ्य और पारदर्शी मंडी ज्ञान पहुंचाना।",
    "about_why_title": "एग्रीमाइंड एआई क्यों बनाया गया?",
    "about_why_p1": "भारतीय अर्थव्यवस्था की रीढ़ होने के बावजूद, हमारे छोटे किसान समय पर फसल सुरक्षा सलाह और मंडी भाव की सटीक जानकारी न मिलने से जूझते हैं।",
    "about_why_p2": "एग्रीमाइंड एआई का उद्देश्य आईसीएआर की सिफारिशों, स्थानीय मौसम और लाइव मंडी भावों को जोड़कर किसानों को एक सुलभ डिजिटल मंच प्रदान करना है।",
    "about_principles_title": "हमारे मार्गदर्शक सिद्धांत",
    "about_principle_1_title": "🔬 पारदर्शी कृषि विज्ञान",
    "about_principle_1_desc": "हम केवल वैज्ञानिक और प्रमाणित तथ्यों पर आधारित सलाह देते हैं। हर उर्वरक मात्रा और समय के पीछे का कृषि तर्क स्पष्ट रूप से समझाया गया है।",
    "about_principle_2_title": "🌐 क्षेत्रीय भाषाई पहुंच",
    "about_principle_2_desc": "कृषि तकनीक तभी उपयोगी है जब वह किसान की अपनी भाषा में हो। एग्रीमाइंड एआई हिंदी, तेलुगु, तमिल और अंग्रेजी में क्षेत्रीय बोलचाल के साथ उपलब्ध है।",
    "about_principle_3_title": "💧 जल संरक्षण प्राथमिकता",
    "about_principle_3_desc": "हर सिंचाई और फसल गणना भूजल संरक्षण, ड्रिप सिंचाई और भूमि की प्राकृतिक उर्वरा शक्ति बनाए रखने को प्राथमिकता देती है।",
    "about_principle_4_title": "⚡ बिना रुकावट तेज गति",
    "about_principle_4_desc": "बिना किसी ऐप डाउनलोड या लॉगिन के, ग्रामीण इलाकों के 2G/3G नेटवर्क पर भी यह वेबसाइट तुरंत लोड होती है।",
    "contact_desc": "हमारे उपकरणों पर प्रतिक्रिया या कृषि विश्वविद्यालयों के साथ साझेदारी के लिए हमारी टीम से संपर्क करें।",
